/* =====================================================================
   CLUB №1 — events.js · ДАННЫЕ АФИШИ
   ---------------------------------------------------------------------
   Источник: операционная таблица маркетинга (лист «Все мероприятия»,
   пересборка 2026-07-26 со страниц живого сайта: даты, времена и виджет-ссылки сняты с кнопок покупки; афиши — артворк событийных страниц) + афиши дизайна с Яндекс.Диска. Времена указаны
   только там, где они подтверждены первоисточником (напечатаны на афише,
   стоят в таблице или в разметке живого сайта); у остальных событий
   time:null — карточка показывает только дату.

   Поля:
     date   ISO-дата события
     time   'HH:MM' | null (не подтверждено)
     title  имя артиста / название шоу (заголовок карточки)
     kind   подпись жанра на CSS-постере (когда нет настоящей афиши)
     format ключ из CLUB1_FORMATS
     poster путь к настоящей афише 1080×1350 (4:5, родной размер карточки;
            старые квадраты 1:1 живут под размытой подложкой) | null → CSS-постер
     photo  фото артиста для CSS-постера | null
     tone   цветовой вариант CSS-постера (cyan/gold/mag/pur/green/sky/mono)
     page   внутренняя страница превью («Подробнее»)
     buy    ПРЯМАЯ виджет-ссылка покупки (intickets/Я.Билеты) | null
     wide   панорама хиро-слайдера 2880×720 (4:1, окно слайдера с правки
            19.08; на телефоне показывается её центральная полоса) | null.
            Старые 12:5 (1920×800) и 16:9 (1680×945) в этом поле — переходные,
            вписываются в окно с размытыми полями
     wideFocus горизонтальная точка кадрирования панорамы на телефоне
            ('42%'); по умолчанию центр. Полоса 180 px показывает ~54 %
            ширины 4:1, и если заголовок ушёл влево от центра, фокус
            сдвигают к нему, чтобы в кадре были и надпись, и лицо
     wide169 переходный арт 16:9 для событий, на которые панорамы ещё нет:
            слайдер показывает его целиком, а не кропает в 12:5. Ставится
            вместе с wide:null; уходит, когда Максим пришлёт панораму
     age    возрастная маркировка | null (не подтверждена)
   ===================================================================== */
/* Партнёрские баннеры хиро-слайдера (Саша 28.08, мокап «Билеты на Яндекс
   Афише»). Это не события: без даты, без карточки в афише, без плашек,
   18+ и кнопок на слайде — весь слайд ведёт по href в новой вкладке. Идут
   перед событиями в порядке массива.
     title  подпись слайда для скринридера
     wide   панорама 4:1 (2880×720) + -540/-640, как у событий
     poster афиша 4:5 (1080×1350) + -540/-640 — слайд на телефоне; там же
            под ней одна кнопка «Купить билеты» по тому же href
     href   куда ведёт слайд
     until  последний день показа (ISO) | null — бессрочно */
window.CLUB1_BANNERS = [
  /* 01.09: слайд ведёт на НАШУ страницу мюзикла, а не на Яндекс.Афишу, и
     показывает панораму Максима 2880×720 вместо прежнего мокапа, собранного
     из обложки Афиши. Живёт до последнего спектакля проката (30.10). Сами
     сеансы заведены событиями ниже с wide:null — слайдер держит баннер, и
     дубля «баннер + карточка шоу» в нём не возникает. */
  {title:'О чём молчат женщины — гастро-мюзикл в Метелице',
   wide:'assets/posters/molchat-wide41.jpg', poster:'assets/posters/molchat-45.jpg',
   href:'molchat.html', until:'2026-10-30'}
];

